/**
 * sync-lucide-mock
 *
 * Scans src/**\/*.{ts,tsx} to collect all lucide-react icon imports,
 * writes the result to src/__tests__/helpers/__generated__/lucide-used-icons.ts,
 * and validates that all vi.mock('lucide-react') calls use buildLucideMock.
 *
 * Usage:
 *   node scripts/sync-lucide-mock.mjs          # sync (write/update generated file)
 *   node scripts/sync-lucide-mock.mjs --check  # check only (exit 1 on drift or violation)
 */

import { readFile, writeFile, readdir, stat, mkdir } from 'node:fs/promises';
import { join, extname, relative } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname } from 'node:path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const FRONTEND_ROOT = join(__dirname, '..');
const SRC_ROOT = join(FRONTEND_ROOT, 'src');
const GENERATED_DIR = join(SRC_ROOT, '__tests__', 'helpers', '__generated__');
const GENERATED_FILE = join(GENERATED_DIR, 'lucide-used-icons.ts');

/** Directories to skip during recursive scan. */
const EXCLUDE_DIRS = new Set([
  'node_modules',
  '.next',
  '__generated__',
  '.git',
  'dist',
  'build',
  'coverage',
]);

/**
 * Recursively walks a directory, yielding file paths that match the given extensions.
 *
 * @param dir - Root directory to walk
 * @param extensions - Set of extensions to include (e.g. new Set(['.ts', '.tsx']))
 * @returns Sorted list of matching file paths
 */
async function walkFiles(dir, extensions) {
  /** @type {string[]} */
  const results = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (EXCLUDE_DIRS.has(entry.name)) continue;
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      const nested = await walkFiles(fullPath, extensions);
      results.push(...nested);
    } else if (entry.isFile() && extensions.has(extname(entry.name))) {
      results.push(fullPath);
    }
  }
  return results.sort();
}

/** Returns true when a file path is a test/spec file (excluded from icon scan). */
function isTestFile(filePath) {
  return /\.(test|spec)\.(ts|tsx)$/.test(filePath);
}

/**
 * Scans non-test .ts/.tsx files under srcRoot and collects every icon name
 * imported from 'lucide-react', returning a sorted, deduplicated array.
 * Test files are intentionally excluded — they mock icons, not use them.
 *
 * @param {string} srcRoot - Path to the src/ directory to scan
 * @returns {Promise<string[]>} Sorted unique icon names
 */
export async function collectUsedIcons(srcRoot) {
  const allFiles = await walkFiles(srcRoot, new Set(['.ts', '.tsx']));
  const files = allFiles.filter((f) => !isTestFile(f));
  const iconSet = new Set();

  // NOTE: Excludes `import type { ... }` — those are TS interfaces, not icon components.
  const importRegex = /import\s+\{([^}]+)\}\s+from\s+['"]lucide-react['"]/gs;

  for (const file of files) {
    const source = await readFile(file, 'utf-8');
    let match;
    importRegex.lastIndex = 0;
    while ((match = importRegex.exec(source)) !== null) {
      const block = match[1];
      for (const raw of block.split(',')) {
        // Handle "IconA as SomeAlias" — extract the original export name only
        const name = raw.replace(/\s+as\s+\w+/g, '').trim();
        if (name && /^[A-Z]/.test(name)) {
          iconSet.add(name);
        }
      }
    }
  }

  return Array.from(iconSet).sort();
}

/**
 * Finds test files that contain vi.mock('lucide-react') but do NOT use
 * buildLucideMock — these are non-compliant static mocks that defeat the
 * self-repairing guarantee.
 *
 * @param {string} srcRoot - Path to the src/ directory to scan
 * @returns {Promise<string[]>} Relative paths of non-compliant test files
 */
export async function findNonCompliantMocks(srcRoot) {
  const files = await walkFiles(srcRoot, new Set(['.ts', '.tsx']));
  const nonCompliant = [];

  for (const file of files) {
    const source = await readFile(file, 'utf-8');
    const hasMock = /vi\.mock\s*\(\s*['"]lucide-react['"]/.test(source);
    if (!hasMock) continue;
    const usesFactory = /buildLucideMock/.test(source);
    if (!usesFactory) {
      nonCompliant.push(relative(FRONTEND_ROOT, file).replace(/\\/g, '/'));
    }
  }

  return nonCompliant;
}

/**
 * Generates the TypeScript source for the lucide-used-icons.ts file.
 *
 * @param {string[]} icons - Sorted, deduplicated icon names
 * @returns {string} File contents to write
 */
function generateOutput(icons) {
  const entries = icons.map((n) => `  '${n}',`).join('\n');
  return (
    `// DO NOT EDIT — generated by scripts/sync-lucide-mock.mjs\n` +
    `// Run: node scripts/sync-lucide-mock.mjs\n\n` +
    `/** All lucide-react icon names currently used in src/. */\n` +
    `export const LUCIDE_USED_ICONS = [\n${entries}\n] as const;\n`
  );
}

/** Reads the current generated file and returns its icon list (or [] if absent). */
async function readCurrentIcons() {
  try {
    const content = await readFile(GENERATED_FILE, 'utf-8');
    // NOTE: `*` (not `+`) to handle single-character icons like 'X'.
    const matches = content.match(/'([A-Z][A-Za-z0-9]*)'/g) ?? [];
    return matches.map((m) => m.slice(1, -1)).sort();
  } catch {
    return [];
  }
}

async function main() {
  const isCheck = process.argv.includes('--check');

  const [icons, nonCompliant] = await Promise.all([
    collectUsedIcons(SRC_ROOT),
    findNonCompliantMocks(SRC_ROOT),
  ]);

  let hasDrift = false;
  let hasViolation = nonCompliant.length > 0;

  if (hasViolation) {
    console.error(
      `\n❌  Non-compliant lucide-react mocks found (use buildLucideMock instead of static objects):\n`,
    );
    for (const f of nonCompliant) {
      console.error(`   ${f}`);
    }
    console.error('');
  }

  if (isCheck) {
    const current = await readCurrentIcons();
    const expected = icons.slice().sort();
    const added = expected.filter((i) => !current.includes(i));
    const removed = current.filter((i) => !expected.includes(i));
    hasDrift = added.length > 0 || removed.length > 0;

    if (hasDrift) {
      console.error('\n❌  lucide-used-icons.ts is out of sync with src/. Run: node scripts/sync-lucide-mock.mjs\n');
      if (added.length) console.error('   Added:  ', added.join(', '));
      if (removed.length) console.error('   Removed:', removed.join(', '));
      console.error('');
    } else {
      console.log('✅  lucide-used-icons.ts is up to date.');
    }

    process.exit(hasDrift || hasViolation ? 1 : 0);
  } else {
    await mkdir(GENERATED_DIR, { recursive: true });
    await writeFile(GENERATED_FILE, generateOutput(icons), 'utf-8');
    console.log(`✅  Wrote ${icons.length} icons to ${relative(FRONTEND_ROOT, GENERATED_FILE).replace(/\\/g, '/')}`);
    if (hasViolation) {
      process.exit(1);
    }
  }
}

// NOTE: Guards CLI execution so the module can be imported as pure functions in tests.
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
